tasks=[]
for i in range(1,5):
    tasks+=json.loads(Path('/home/claude/book/tasks/t%d.json'%i).read_text())
tasks=sorted(tasks,key=lambda t:t['lesson'])
assert [t['lesson'] for t in tasks]==list(range(1,37))
C['tasks']=tasks
(H/'content.json').write_text(json.dumps(C,ensure_ascii=False,indent=1)+'\n')
print('ok',len(tasks),len(C['keypoints']))
